#!/bin/bash
whois $1 | awk -F': ' 'BEGIN {IGNORECASE=1; split("Registrant,Admin,Tech", sections, ","); split("Name,Organization,Street,City,State/Province,Postal Code,Country,Phone,Phone Ext,Fax,Fax Ext,Email", fields, ",")} {gsub(/^[ \t]+|[ \t]+$/, "", $1); gsub(/^[ \t]+|[ \t]+$/, "", $2); if ($1 ~ /^(Registrant|Admin|Tech) /) {split($1, parts, " "); sec=parts[1]; fld=substr($1, length(sec)+2); data[sec, fld]=$2}} END {for (i=1; i<=3; i++) {s=sections[i]; for (j=1; j<=12; j++) {f=fields[j]; k=s" "f; val=data[s, f]; if (f ~ /Street/) val=val" "; if (f ~ /Ext/) f=f":"; printf "%s %s,%s%s", s, f, val, (i==3 && j==12) ? "" : ORS}}}'
